const topics=["Network Layer Design Issues", "Unicast, Multicast, Broadcast", "IPv4 Classful Addressing", "IPv4 Classless Addressing", "Subnetting and Supernetting Design Problems", "Network Address Translation", "IPv6", "Dijkstra's Shortest Path Algorithm", "Link State Routing", "Distance Vector Routing", "ARP, RARP, ICMP, IGMP", "Open Loop and Closed Loop Congestion Control"];
const practice=["IPv4 class identification", "Binary and decimal conversion", "CIDR and subnet mask conversion", "Network address calculation", "Broadcast address calculation", "Usable host range calculation", "Fixed Length Subnet Masking (FLSM)", "Variable Length Subnet Masking (VLSM)", "Supernetting", "IPv6 compression and expansion", "Dijkstra's Algorithm", "Link State Routing", "Distance Vector Routing"];
const lectures=sections.flatMap(s=>s.rows);
const speeds=[1,1.25,1.5,1.75,2];
const stages=['Not started','Practising','Mastered'];
const defaults={theme:'light',speed:1,'m3/lastActive':''};
const key=(lecture,field)=>'m3/'+lecture.uid+'/'+field;
const pk=p=>'m3/practice/'+p.toLowerCase().replace(/[^a-z0-9]+/g,'-');
for(const l of lectures){defaults[key(l,'done')]=false;defaults[key(l,'revision')]=false;defaults[key(l,'note')]='';defaults[key(l,'position')]=0}
for(const p of practice)defaults[pk(p)]=stages[0];
function valid(data){return data && typeof data==='object' && !Array.isArray(data) && Object.entries(data).every(([k,v])=>Object.hasOwn(defaults,k)&&(k.startsWith('quiz/')?validQuizValue(k,v):k==='m3/lastActive'?v===''||lectures.some(l=>l.uid===v):k.endsWith('/position')?Number.isFinite(v)&&v>=0&&v<86400:k==='theme'?['dark','light'].includes(v):k==='speed'?speeds.includes(v):k.includes('/practice/')?stages.includes(v):k.endsWith('/note')?typeof v==='string'&&v.length<=8000:typeof v==='boolean'))}

const aliases=new Map();
for(const l of lectures)for(const id of [l.id,l.legacyVideo].filter(Boolean))
 for(const field of ['done','revision','note'])aliases.set('m3/'+id+'/'+field,key(l,field));
function migrate(data){
 if(!data||typeof data!=='object'||Array.isArray(data))return data;
 const result={...data};
 for(const [old,current] of aliases)if(Object.hasOwn(result,old)){
  if(!Object.hasOwn(result,current))result[current]=result[old];
  delete result[old];
 }
 return result;
}
function nextLecture(items,record,last){
 return items.find(l=>l.uid===last&&!record[key(l,'done')])||items.find(l=>!record[key(l,'done')]);
}

const quizModules = ['m3','m4'];
const cardPattern = /^m[34]-(0[1-9]|[1-4][0-9]|50)$/;
const roundKey = mod => 'quiz/'+mod+'/round';
const markKey = id => 'quiz/card/'+id;
const trackKey = mod => 'quiz/'+mod+'/history';
const whole = value => Number.isSafeInteger(value) && value >= 0;
function isRound(value,mod) {
 if(value===null) return true;
 if(!value || typeof value!=='object' || !Array.isArray(value.cards) || !Array.isArray(value.answers)) return false;
 const count=value.cards.length;
 return count>=1 && count<=50 && new Set(value.cards.map(c=>c?.id)).size===count &&
 value.cards.every(c=>c && cardPattern.test(c.id) && c.id.startsWith(mod+'-') && ['012','021','102','120','201','210'].includes(c.order)) &&
 whole(value.index) && value.index<=count && value.answers.length>=value.index &&
 value.answers.length<=Math.min(count,value.index+1) && value.answers.every(a=>[0,1,2].includes(a));
}
function validQuizValue(k,v) {
 if(k.startsWith('quiz/card/')) return Array.isArray(v)&&v.length===3&&whole(v[0])&&whole(v[1])&&v[1]<=v[0]&&typeof v[2]==='boolean';
 if(k.endsWith('/round')) return isRound(v,k.split('/')[1]);
 return Array.isArray(v)&&v.length<=20&&v.every(r=>Array.isArray(r)&&r.length===3&&whole(r[0])&&r[0]<=8640000000000000&&whole(r[1])&&whole(r[2])&&r[2]>=1&&r[2]<=50&&r[1]<=r[2]);
}
for(const mod of quizModules) {
 defaults[roundKey(mod)]=null;defaults[trackKey(mod)]=[];
 for(let i=1;i<=50;i++)defaults[markKey(mod+'-'+String(i).padStart(2,'0'))]=[0,0,false];
}

// Build injects the assets and the same validation used by the dashboard.
export default {async fetch(request,env){
 const url=new URL(request.url);
 const user=request.headers.get('oai-authenticated-user-id')||'';
 if(url.pathname!=='/progress'){
  const path=url.pathname==='/'?'/index.html':url.pathname;
  if(!Object.hasOwn(assets,path))return new Response('Page not found',{status:404});
  const type=path.endsWith('.js')?'text/javascript':path.endsWith('.css')?'text/css':'text/html';
  if(path==='/index.html'){
   const html=assets[path].replace('name="notebook-account" content=""','name="notebook-account" content="'+encodeURIComponent(user)+'"');
   return new Response(html,{headers:{'content-type':'text/html; charset=utf-8','cache-control':'private, no-store'}});
  }
  return new Response(assets[path],{headers:{'content-type':type+'; charset=utf-8','cache-control':'no-cache','x-content-type-options':'nosniff'}})
 }
 const reply=(value,status=200)=>Response.json(value,{status,headers:{'cache-control':'no-store'}});

 if(!user)return reply({error:'Sign-in required'},401);
 if(request.headers.get('X-Notebook-Account')!==encodeURIComponent(user))return reply({error:'Account changed'},409);
 if(!env.BUCKET)return reply({error:'Storage unavailable'},503);
 const objectKey='progress/v1/'+encodeURIComponent(user);
 try{
  if(request.method==='GET'){const obj=await env.BUCKET.get(objectKey);return reply(migrate(obj?await obj.json():{}))}
  if(request.method!=='PATCH')return reply({},405);
  if(request.headers.get('origin')!==url.origin)return reply({},403);
  const body=await request.text();if(body.length>1500000)return reply({},413);
  let delta;try{delta=migrate(JSON.parse(body))}catch{return reply({},400)}
  if(!valid(delta))return reply({},400);
  for(let i=0;i<5;i++){
   const obj=await env.BUCKET.get(objectKey);
   const prior=migrate(obj?await obj.json():{});
   const merged=request.headers.get('X-Import-Guest')==='1'?{...delta,...prior}:{...prior,...delta};
   const saved=await env.BUCKET.put(objectKey,JSON.stringify(merged),{onlyIf:obj?{etagMatches:obj.etag}:{etagDoesNotMatch:'*'}});
   if(saved)return reply(merged)
  }return reply({},409)
 }catch{return reply({error:'Storage unavailable'},503)}
}}
